// Claude 사용량 API 응답 해석: Claude Code의 /usage 가 받는 것과 같은 응답(api.anthropic.com/api/oauth/usage)을
// mod가 세션의 자격 증명 핸들($.session.authorize)로 직접 받거나, 그게 안 될 때는 상태줄 스크립트
// (awesome-statusline)가 같은 응답을 저장해 둔 파일(.claude_usage_cache)에서 읽는다. 토큰은 mod에 오지 않는다.
//
//   { "five_hour": { "utilization": 3.0, "resets_at": "…" }, "seven_day": { … },
//     "limits": [ { "kind": "weekly_scoped", "percent": 100, "resets_at": "…",
//                   "scope": { "model": { "display_name": "Fable" } } }, … ] }
//
// 엔진이 응답마다 주는 한도(five_hour, seven_day)에는 모델별 주간 한도가 없어서,
// Fable 같은 모델별 한도는 여기서만 얻는다.

export type CachedWindow = {
  /** 사용한 비율, 0–100 */
  pct: number
  /** 리셋 시각(ms, epoch). 모르면 없음 */
  resetsAtMs?: number
}

export type ClaudeCache = {
  /** 받은 시각(ms): API면 받은 때, 파일이면 파일이 마지막으로 바뀐 때 */
  at: number
  /** 어디서 왔는지: 사용량 API 직접(api) · 상태줄 캐시 파일(file). 없으면 옛 기록 */
  source?: 'api' | 'file'
  fiveHour?: CachedWindow
  sevenDay?: CachedWindow
  /** 모델별 주간 한도: 이름(예: Fable)과 창 */
  scoped: { name: string; window: CachedWindow }[]
}

const num = (v: unknown): number | undefined => (typeof v === 'number' && Number.isFinite(v) ? v : undefined)

const time = (v: unknown): number | undefined => {
  if (typeof v !== 'string') return undefined
  const t = Date.parse(v)
  return Number.isFinite(t) ? t : undefined
}

function windowOf(raw: unknown, key: 'utilization' | 'percent'): CachedWindow | undefined {
  if (!raw || typeof raw !== 'object') return undefined
  const r = raw as Record<string, unknown>
  const pct = num(r[key])
  return pct === undefined ? undefined : { pct, resetsAtMs: time(r.resets_at) }
}

/** 캐시 파일 내용 → 한도. 모양이 다르면 undefined */
export function parseClaudeCache(text: string, at: number): ClaudeCache | undefined {
  let o: Record<string, unknown>
  try {
    o = JSON.parse(text) as Record<string, unknown>
  } catch {
    return undefined
  }
  if (!o || typeof o !== 'object') return undefined
  const cache: ClaudeCache = { at, fiveHour: windowOf(o.five_hour, 'utilization'), sevenDay: windowOf(o.seven_day, 'utilization'), scoped: [] }
  for (const l of Array.isArray(o.limits) ? o.limits : []) {
    if (!l || typeof l !== 'object') continue
    const limit = l as Record<string, unknown>
    if (limit.kind !== 'weekly_scoped') continue
    const scope = (limit.scope ?? {}) as Record<string, Record<string, unknown> | null>
    const name = scope.model?.display_name ?? scope.surface?.display_name
    const w = windowOf(limit, 'percent')
    if (typeof name === 'string' && name && w && !cache.scoped.some(s => s.name === name)) cache.scoped.push({ name, window: w })
  }
  return cache.fiveHour || cache.sevenDay || cache.scoped.length > 0 ? cache : undefined
}

files.hooks/codex.ts:
// Codex 사용량 읽기: Codex CLI·앱이 남기는 세션 기록(rollout-*.jsonl)의
// token_count 이벤트에 들어 있는 rate_limits 스냅숏을 찾아 해석한다.
//
//   ~/.codex/sessions/YYYY/MM/DD/rollout-....jsonl
//   {"timestamp":"…","type":"event_msg","payload":{"type":"token_count",
//     "info":{…},"rate_limits":{"primary":{"used_percent":12.0,
//     "window_minutes":300,"resets_at":1790713159},"secondary":{…}}}}
//
// 버전마다 모양이 조금씩 달라서(resets_in_seconds ↔ resets_at, primary가
// 주간인 경우, rate_limits가 null인 줄) 모두 너그럽게 받아들인다.

export type Window = {
  /** 사용한 비율, 0–100 */
  pct: number
  /** 창 길이(분). 300 ≈ 5시간, 10080 = 7일 */
  windowMin?: number
  /** 리셋 시각(ms, epoch). 모르면 없음 */
  resetsAtMs?: number
}

export type CodexSnapshot = {
  /** 이 스냅숏이 기록된 시각(ms) */
  at: number
  short?: Window
  week?: Window
  plan?: string
  /** 어디서 왔는지: 앱 서버에서 방금 받음(live) · 세션 기록에서 읽음(log). 없으면 옛 기록 */
  source?: 'live' | 'log'
}

/** 앱 서버(`account/rateLimits/read`)의 답 → 스냅숏. 창 이름이 camelCase이고 resetsAt이 초 단위다 */
export function snapshotFromAppServer(result: unknown, at: number): CodexSnapshot | undefined {
  if (!result || typeof result !== 'object') return undefined
  const rl = (result as { rateLimits?: unknown }).rateLimits
  if (!rl || typeof rl !== 'object') return undefined
  const r = rl as { primary?: unknown; secondary?: unknown; planType?: unknown }
  const win = (raw: unknown): Window | undefined => {
    if (!raw || typeof raw !== 'object') return undefined
    const w = raw as { usedPercent?: unknown; windowDurationMins?: unknown; resetsAt?: unknown }
    const pct = num(w.usedPercent)
    if (pct === undefined) return undefined
    const resets = num(w.resetsAt)
    return { pct, windowMin: num(w.windowDurationMins), resetsAtMs: resets !== undefined && resets > 0 ? (resets < 1e12 ? resets * 1000 : resets) : undefined }
  }
  const wins = [win(r.primary), win(r.secondary)]
  if (!wins[0] && !wins[1]) return undefined
  const snap: CodexSnapshot = { at, source: 'live' }
  wins.forEach((w, i) => {
    if (!w) return
    const isShort = w.windowMin !== undefined ? w.windowMin <= 1440 : i === 0
    if (isShort) snap.short ??= w
    else snap.week ??= w
  })
  if (typeof r.planType === 'string') snap.plan = r.planType
  return snap
}

type RawWindow = {
  used_percent?: unknown
  window_minutes?: unknown
  resets_at?: unknown
  resets_in_seconds?: unknown
}

const num = (v: unknown): number | undefined =>
  typeof v === 'number' && Number.isFinite(v) ? v : typeof v === 'string' && v.trim() !== '' && Number.isFinite(Number(v)) ? Number(v) : undefined

function toWindow(raw: unknown, lineAt: number): Window | undefined {
  if (!raw || typeof raw !== 'object') return undefined
  const r = raw as RawWindow
  const pct = num(r.used_percent)
  if (pct === undefined) return undefined
  const windowMin = num(r.window_minutes)
  let resetsAtMs: number | undefined
  const at = num(r.resets_at)
  if (at !== undefined && at > 0) {
    resetsAtMs = at < 1e12 ? at * 1000 : at
  } else if (typeof r.resets_at === 'string' && r.resets_at && !Number.isFinite(Number(r.resets_at))) {
    const t = Date.parse(r.resets_at)
    if (Number.isFinite(t)) resetsAtMs = t
  } else {
    const inSec = num(r.resets_in_seconds)
    if (inSec !== undefined && lineAt > 0) resetsAtMs = lineAt + inSec * 1000
  }
  return { pct, windowMin, resetsAtMs }
}

/** 한 줄(JSON)에서 스냅숏을 꺼낸다. rate_limits가 없거나 비었으면 undefined */
export function parseLine(line: string): CodexSnapshot | undefined {
  if (!line.includes('rate_limits')) return undefined
  let o: Record<string, unknown>
  try {
    o = JSON.parse(line) as Record<string, unknown>
  } catch {
    return undefined
  }
  const payload = (o.payload ?? o.msg ?? {}) as Record<string, unknown>
  const rl = (payload.rate_limits ?? o.rate_limits) as Record<string, unknown> | null | undefined
  if (!rl || typeof rl !== 'object') return undefined
  const ts = typeof o.timestamp === 'string' ? Date.parse(o.timestamp) : NaN
  const lineAt = Number.isFinite(ts) ? ts : 0
  const wins = [toWindow(rl.primary, lineAt), toWindow(rl.secondary, lineAt)]
  if (!wins[0] && !wins[1]) return undefined

  const snap: CodexSnapshot = { at: lineAt }
  wins.forEach((w, i) => {
    if (!w) return
    // 창 길이로 분류한다(primary가 주간인 버전이 있음). 길이를 모르면 primary=5시간
    const isShort = w.windowMin !== undefined ? w.windowMin <= 1440 : i === 0
    if (isShort) snap.short ??= w
    else snap.week ??= w
  })
  const plan = rl.plan_type
  if (typeof plan === 'string') snap.plan = plan
  return snap
}

/** 파일 내용에서 가장 마지막(최신) 스냅숏 */
export function lastSnapshot(text: string): CodexSnapshot | undefined {
  const lines = text.split('\n')
  for (let i = lines.length - 1; i >= 0; i--) {
    const s = parseLine(lines[i] ?? '')
    if (s) return s
  }
  return undefined
}

/** 리셋 시각이 지났으면 그 창은 0%로 본다 */
export function effectivePct(w: Window | undefined, now: number): number | undefined {
  if (!w) return undefined
  if (w.resetsAtMs !== undefined && now >= w.resetsAtMs) return 0
  return w.pct
}

files.hooks/format.ts:
// 막대·색·남은 시간 표시와 띠의 행 모양. 시간대 데이터에 기대지 않도록 "몇 시간 후"로 쓴다.

/** 막대 한 칸(눈금 하나): 사용량 표시에 쓰는 한 창 */
export type Meter = {
  label: string
  /** 사용한 비율, 0–100. 없으면 이 창은 "—"로 그린다 */
  pct?: number
  resetsAtMs?: number
}

/** 띠의 한 줄: Claude 또는 Codex */
export type BandRow = {
  name: string
  /** 이름 색(#rrggbb) */
  color: string
  /** 열마다 한 칸. undefined는 빈칸(다른 줄만 그 열이 있을 때) */
  meters: (Meter | undefined)[]
  /** 줄 끝: 컨텍스트 같은 값 하나와 흐린 메모 */
  tail?: { label: string; pct: number }
  note?: string
}

export const BAR_WIDTH = 10

/** 50% 미만 초록, 80% 미만 주황, 그 이상 빨강. 밝은·어두운 테마 모두에서 읽히는 중간 밝기 */
export const hexFor = (pct: number): string => (pct < 50 ? '#2f9e44' : pct < 80 ? '#e8890c' : '#e5484d')

/** 터미널 테마 키 */
export const colorFor = (pct: number): string => (pct < 50 ? 'success' : pct < 80 ? 'warning' : 'error')

export const pctText = (pct: number): string => `${Math.round(pct)}%`

const EIGHTHS = ['', '▏', '▎', '▍', '▌', '▋', '▊', '▉']

/** 1/8칸까지 나누는 막대: [채운 부분, 빈 부분] */
export function barParts(pct: number, width = BAR_WIDTH): [string, string] {
  const eighths = Math.round((Math.max(0, Math.min(100, pct)) / 100) * width * 8)
  const full = Math.floor(eighths / 8)
  const part = EIGHTHS[eighths % 8] ?? ''
  const filled = '█'.repeat(full) + part
  return [filled, '░'.repeat(width - full - (part ? 1 : 0))]
}

/** 예전 모양(채움+빈칸을 한 문자열로) */
export const bar = (pct: number, width = BAR_WIDTH): string => barParts(pct, width).join('')

/** 남은 시간: "3일 4시간", "2시간 13분", "45분", "곧" */
export function untilText(ms: number): string {
  if (ms <= 60_000) return '곧'
  const totalMin = Math.floor(ms / 60_000)
  const d = Math.floor(totalMin / 1440)
  const h = Math.floor((totalMin % 1440) / 60)
  const m = totalMin % 60
  if (d > 0) return h > 0 ? `${d}일 ${h}시간` : `${d}일`
  if (h > 0) return m > 0 ? `${h}시간 ${m}분` : `${h}시간`
  return `${m}분`
}

/** 지난 시간: "방금", "3분 전", "2시간 전", "1일 전" */
export function agoText(ms: number): string {
  if (ms < 60_000) return '방금'
  const min = Math.floor(ms / 60_000)
  if (min < 60) return `${min}분 전`
  const h = Math.floor(min / 60)
  if (h < 24) return `${h}시간 전`
  return `${Math.floor(h / 24)}일 전`
}

/** 한도가 다시 차는 때까지: "1일 13시간 후" */
export const resetText = (m: Meter, now: number): string =>
  m.pct !== undefined && m.resetsAtMs !== undefined && m.resetsAtMs > now ? `${untilText(m.resetsAtMs - now)} 후` : ''

/** 터미널에서 차지하는 칸 수(한글·전각은 2칸) */
export function cellWidth(s: string): number {
  let w = 0
  for (const ch of s) {
    const c = ch.codePointAt(0) ?? 0
    w += (c >= 0x1100 && c <= 0x115f) || (c >= 0x2e80 && c <= 0xa4cf) || (c >= 0xac00 && c <= 0xd7a3) || (c >= 0xf900 && c <= 0xfaff) || (c >= 0xfe30 && c <= 0xfe4f) || (c >= 0xff00 && c <= 0xff60) ? 2 : 1
  }
  return w
}

export const padCells = (s: string, width: number): string => s + ' '.repeat(Math.max(0, width - cellWidth(s)))
export const padCellsStart = (s: string, width: number): string => ' '.repeat(Math.max(0, width - cellWidth(s))) + s

/** 열마다 가장 긴 이름표·리셋 글자 너비(칸) */
export function columnsOf(rows: BandRow[], now: number, measure: (s: string) => number) {
  const n = Math.max(0, ...rows.map(r => r.meters.length))
  return Array.from({ length: n }, (_, c) => {
    const ms = rows.map(r => r.meters[c]).filter((m): m is Meter => m !== undefined)
    return {
      label: Math.max(0, ...ms.map(m => measure(m.label))),
      reset: Math.max(0, ...ms.map(m => measure(resetText(m, now)))),
    }
  })
}

